<?php get_header(); ?><div class="wrap section"><div class="breadcrumb"><a href="<?php echo esc_url(bcst_home()); ?>"><?php echo esc_html(bcst_t('Home')); ?></a> / <?php echo esc_html(is_search()?bcst_t('Search'):(is_post_type_archive('bcst_product')?bcst_t('Products'):bcst_t('Insights'))); ?></div><h1><?php if(is_search())echo esc_html(bcst_t('Search').': '.get_search_query());elseif(is_tax('bcst_category'))single_term_title();elseif(is_post_type_archive('bcst_product'))echo esc_html(bcst_t('Products'));elseif(is_archive())the_archive_title();else echo esc_html(bcst_t('Insights')); ?></h1>
<?php get_search_form();if(is_tax('bcst_category')||is_post_type_archive('bcst_product')){$current=is_tax()?get_queried_object_id():0;echo '<div class="content">'.wp_kses_post(term_description()).'</div><ul class="categories">';$terms=get_terms(array('taxonomy'=>'bcst_category','parent'=>$current,'hide_empty'=>true));if(!is_wp_error($terms))foreach($terms as $term)echo '<li><a href="'.esc_url(get_term_link($term)).'">'.esc_html($term->name).'</a></li>';echo '</ul>';} ?>
